const SITTING_KEYS = ['_messages', '_msgFetch', '_shareFetch', '_signChecking', '_triaging'];
const dropSittingKeys = c => { if (c && typeof c === 'object') for (const k of SITTING_KEYS) delete c[k]; return c; };
