addColumnIfMissing('users', 'totp_secret', 'TEXT');
addColumnIfMissing('users', 'totp_pending', 'TEXT');
addColumnIfMissing('users', 'totp_recovery', 'TEXT');
addColumnIfMissing('sessions', 'expires_at', 'TEXT');
