  if (w) { const briefs = copilotBriefIds(ctx); cs = cs.filter(c => graphWhereHit(copilotCardOf(c, briefs, effOf), w, { daysUntil: copilotDaysUntil, folderIdOf: () => '' })); }
  if (filter.status) cs = cs.filter(c => (c.status || '') === filter.status);
