  EQ: 'Equipment Lease', WH: 'Warehousing', FF: 'Distribution Logistics',
  DA: 'Distributor', RL: 'Retail Listing', MK: 'Marketing Services',
  ND: 'NDA', LE: 'Lease', PS: 'Professional Services',
